<?php
require_once __DIR__.'/legacy_class_links.php';
function sc_e(mixed $v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$scReady=special_classes_ready($koneksi);$scEdit=null;$scDelete=null;$scMembers=null;$scError='';
$scQuery=is_string($_GET['special_q']??null)?mb_substr(trim($_GET['special_q']),0,100):'';
$scStatus=in_array($_GET['special_status']??'', ['active','inactive','all'],true)?$_GET['special_status']:'all';$scPage=max(1,min(100000,(int)($_GET['special_page']??1)));$scRows=[];$scTotal=0;$scSources=[];
$scOld=$_SESSION['special_old']??[];unset($_SESSION['special_old']);
if($scReady){
    $scEditId=(int)($_GET['special_edit']??(!empty($customEdit)?$customEdit['id']:0));if($scEditId){$scEdit=class_find($koneksi,$scEditId);if(!$scEdit||class_kind($scEdit)!=='custom'){$scEdit=null;$scError='Kelas khusus tidak ditemukan pada unit ini.';}}
    $scWhere="(mk.jenis IN ('custom','out') OR (mk.tingkat=0 AND UPPER(mk.kode_rombel) REGEXP '^ALUMNI20[0-9]{2}$'))";
    $scKinds=['custom'=>'Kegiatan / Rekening','alumni'=>'Alumni','out'=>'Siswa keluar'];$scKind=is_string($_GET['special_kind']??null)&&isset($scKinds[$_GET['special_kind']])?$_GET['special_kind']:'';
    $scMemberSql=special_class_members_sql($koneksi);
$scArgs=[];if($scQuery!==''){$scWhere.=' AND (mk.nama_custom LIKE ? OR mk.kode_rombel LIKE ?';$scArgs[]='%'.$scQuery.'%';$scArgs[]='%'.$scQuery.'%';if(lop_ready($koneksi)){$scWhere.=' OR EXISTS(SELECT 1 FROM legacy_op_groups cg WHERE cg.master_kelas_id=mk.id AND cg.unit_id=mk.unit_id AND (cg.code LIKE ? OR cg.aliases LIKE ?))';$scArgs[]='%'.$scQuery.'%';$scArgs[]='%'.$scQuery.'%';}$scWhere.=')';}if($scStatus!=='all'){$scWhere.=' AND mk.is_active=?';$scArgs[]=$scStatus==='active'?1:0;}
    if($scKind!==''){$scWhere.=$scKind==='alumni'?" AND (mk.tingkat=0 AND UPPER(mk.kode_rombel) REGEXP '^ALUMNI20[0-9]{2}$')":' AND mk.jenis=?';if($scKind!=='alumni')$scArgs[]=$scKind;}
    $scTotal=(int)special_class_query($koneksi,'SELECT COUNT(*) n FROM master_kelas mk WHERE '.$scWhere,$scArgs)->fetch_assoc()['n'];$scPage=min($scPage,max(1,(int)ceil($scTotal/25)));
    $scRows=special_class_query($koneksi,'SELECT mk.*,(SELECT COUNT(*) FROM (SELECT DISTINCT unit_id,owner_type,id,class_id FROM ('.$scMemberSql.') members_source) members WHERE members.class_id=mk.id AND members.unit_id=mk.unit_id) members FROM master_kelas mk WHERE '.$scWhere.' ORDER BY mk.nama_custom,mk.id LIMIT 25 OFFSET '.(($scPage-1)*25),$scArgs)->fetch_all(MYSQLI_ASSOC);
    if($scRows&&lop_ready($koneksi)){$ids=array_column($scRows,'id');$refs=special_class_query($koneksi,'SELECT master_kelas_id,code FROM legacy_op_groups WHERE master_kelas_id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY code',$ids)->fetch_all(MYSQLI_ASSOC);foreach($refs as $ref)$scSources[(int)$ref['master_kelas_id']][]=$ref['code'];}
    foreach(['special_delete'=>'scDelete','special_members'=>'scMembers'] as $param=>$var)if(isset($_GET[$param])){$r=class_find($koneksi,(int)$_GET[$param]);if($r&&($param==='special_members'?in_array(class_kind($r),['custom','alumni','out'],true):class_kind($r)==='custom'))$$var=$r;else $scError='Kelas khusus tidak ditemukan pada unit ini.';}
}
$scContext=['special_q'=>$scQuery,'special_kind'=>$scKind??'','special_status'=>$scStatus,'special_page'=>$scPage,'special_member_page'=>max(1,(int)($_GET['special_member_page']??1))];
$scUrl=static fn(array $extra=[]):string=>'master_kelas.php?'.http_build_query(array_replace($scContext,$extra)).'#special-classes';
?>
<section class="main-card master-modern-card special-classes" id="special-classes" aria-labelledby="special-classes-title">
  <div class="class-panel-heading"><span class="class-workspace-icon"><?= master_workspace_icon('layers') ?></span><div><h2 id="special-classes-title">Kelas Khusus</h2><p>Alumni, siswa keluar, kegiatan, dan rekening khusus dalam satu daftar. Tidak mengikuti SPP atau kenaikan kelas otomatis.</p></div><span class="sc-count"><?= number_format($scTotal,0,',','.') ?> kelas</span></div>
  <?php if($scError): ?><div class="alert alert-warning" role="alert"><?= sc_e($scError) ?></div><?php endif; ?>
  <?php if(!$scReady): ?><div class="alert alert-warning">Kelas Khusus belum siap. Administrator perlu memasang skema melalui CLI sesuai panduan Kelas Khusus.</div>
  <?php else: ?>
  <?php if(!unit_all_readonly()): ?><details class="sc-form-panel" id="special-class-form" <?= $scEdit||isset($_GET['special_new'])||$scOld?'open':'' ?>><summary><?= master_workspace_icon('plus') ?> <?= $scEdit?'Edit Kelas Khusus':'Tambah Kelas Khusus' ?></summary><form method="post" class="sc-form">
    <input type="hidden" name="csrf_token" value="<?= sc_e($_SESSION['csrf_master_kelas']) ?>"><input type="hidden" name="aksi" value="<?= $scEdit?'update_custom':'tambah_custom' ?>"><input type="hidden" name="id" value="<?= (int)($scEdit['id']??0) ?>"><input type="hidden" name="special_request" value="<?= bin2hex(random_bytes(16)) ?>"><?php if($scEdit): ?><input type="hidden" name="special_version" value="<?= sc_e(special_class_version($scEdit)) ?>"><?php endif; ?>
    <label class="field-row"><span class="field-label">Nama Kelas</span><input class="field-input" name="nama_custom" maxlength="100" required placeholder="Contoh: BTQ atau Tabungan Guru" value="<?= sc_e($scOld['nama_custom']??$scEdit['nama_custom']??'') ?>"><small>Nama tampil sesuai ejaan ini, tanpa awalan tingkat.</small></label>
    <label class="field-row"><span class="field-label">Status</span><select class="field-input" name="is_active"><option value="1" <?= (string)($scOld['is_active']??$scEdit['is_active']??1)==='1'?'selected':'' ?>>Aktif</option><option value="0" <?= (string)($scOld['is_active']??$scEdit['is_active']??1)==='0'?'selected':'' ?>>Nonaktif</option></select><small>Nonaktif tidak menghapus anggota atau histori.</small></label>
    <div class="sc-actions"><button class="btn btn-primary"><?= master_workspace_icon('save') ?> <?= $scEdit?'Simpan Perubahan':'Simpan Kelas Khusus' ?></button><a class="btn btn-ghost" href="<?= sc_e($scUrl()) ?>">Batal</a></div>
  </form></details><?php endif; ?>
  <form method="get" action="master_kelas.php#special-classes" class="sc-search"><label class="field-row"><span class="field-label">Cari Kelas Khusus</span><input name="special_q" class="field-input" maxlength="100" value="<?= sc_e($scQuery) ?>" placeholder="Nama kelas khusus"></label><label class="field-row"><span class="field-label">Status</span><select name="special_status" class="field-input"><?php foreach(['all'=>'Semua status','active'=>'Aktif','inactive'=>'Nonaktif'] as $v=>$label): ?><option value="<?= $v ?>" <?= $scStatus===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="field-row"><span class="field-label">Jenis Kelas</span><select name="special_kind" class="field-input"><option value="">Semua nonakademik</option><?php foreach($scKinds as $v=>$text): ?><option value="<?= $v ?>" <?= $scKind===$v?'selected':'' ?>><?= $text ?></option><?php endforeach; ?></select></label><div class="sc-actions"><button class="btn btn-primary">Cari</button><a class="btn btn-ghost" href="master_kelas.php#special-classes">Reset</a></div></form>
  <?php if(!$scRows): ?><div class="sc-empty"><h3><?= $scQuery!==''?'Kelas khusus tidak ditemukan':'Belum ada kelas khusus pada filter ini' ?></h3><p><?= $scQuery!==''?'Ubah kata kunci atau reset pencarian.':'Gunakan Tambah Kelas Khusus untuk membuat kelompok seperti BTQ, GK, atau Tabungan Guru.' ?></p></div><?php else: ?>
  <div class="sc-table-wrap"><table class="sc-table"><thead><tr><th>Nama Kelas</th><th>Status</th><th>Anggota</th><th>Tindakan</th></tr></thead><tbody><?php foreach($scRows as $sc): ?><tr><td data-label="Nama Kelas"><strong><?= sc_e(class_label($sc)) ?></strong><?php if(isset($scSources[(int)$sc['id']])): ?><details class="sc-source"><summary>Asal Legacy</summary><small><?= sc_e(implode(', ',$scSources[(int)$sc['id']])) ?></small></details><?php endif; ?><small><?= sc_e($scKinds[class_kind($sc)]??'Nonakademik') ?><?= unit_all_readonly()?' · '.sc_e(unit_label((int)$sc['unit_id'])):'' ?></small></td><td data-label="Status"><span class="master-status <?= $sc['is_active']?'is-active':'is-inactive' ?>"><?= $sc['is_active']?'Aktif':'Nonaktif' ?></span></td><td data-label="Anggota"><?= number_format((int)$sc['members'],0,',','.') ?></td><td data-label="Tindakan"><div class="sc-row-actions"><a class="btn btn-ghost" href="<?= sc_e($scUrl(['special_members'=>$sc['id']])) ?>">Lihat Anggota</a><?php if(isset($scSources[(int)$sc['id']])): ?><a class="btn btn-ghost" href="<?= sc_e('legacy_accounts.php?'.http_build_query(['class_id'=>$sc['id']]+$scContext)) ?>">Rekening &amp; Transaksi</a><?php endif; ?><?php if(!unit_all_readonly()&&class_kind($sc)==='custom'): ?><a class="btn-tbl btn-tbl-edit" href="<?= sc_e($scUrl(['special_edit'=>$sc['id']])) ?>">Edit</a><form method="post"><input type="hidden" name="csrf_token" value="<?= sc_e($_SESSION['csrf_master_kelas']) ?>"><input type="hidden" name="aksi" value="toggle"><input type="hidden" name="id" value="<?= (int)$sc['id'] ?>"><input type="hidden" name="special_version" value="<?= sc_e(special_class_version($sc)) ?>"><input type="hidden" name="target_active" value="<?= $sc['is_active']?'0':'1' ?>"><button class="btn-tbl btn-tbl-toggle"><?= $sc['is_active']?'Nonaktifkan':'Aktifkan' ?></button></form><a class="btn-tbl btn-tbl-delete" href="<?= sc_e($scUrl(['special_delete'=>$sc['id']])) ?>">Hapus</a><?php elseif(class_kind($sc)!=='custom'): ?><small class="sc-managed">Dikelola sistem</small><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
  <nav class="sc-pagination" aria-label="Halaman kelas khusus"><span>Halaman <?= $scPage ?> dari <?= max(1,(int)ceil($scTotal/25)) ?> · 25 per halaman</span><div class="sc-actions"><?php foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $delta=>$label): $next=$scPage+$delta;if($next<1||($next-1)*25>=$scTotal)continue; ?><a class="btn btn-ghost" href="<?= sc_e($scUrl(['special_page'=>$next])) ?>"><?= $label ?></a><?php endforeach; ?></div></nav>
  <?php if($scMembers):
    $scMemberClass=(int)$scMembers['id'];
    $scMemberFrom=' FROM (SELECT DISTINCT unit_id,owner_type,id,name,identity,is_active,class_id,batch_id,owner_id FROM ('.$scMemberSql.') source_members) members WHERE class_id=?';
    $scMemberTotal=(int)special_class_query($koneksi,'SELECT COUNT(*)'.$scMemberFrom,[$scMemberClass])->fetch_row()[0];
    $scMemberPage=max(1,min((int)($_GET['special_member_page']??1),max(1,(int)ceil($scMemberTotal/25))));
    $members=special_class_query($koneksi,'SELECT *'.$scMemberFrom.' ORDER BY name,id LIMIT 25 OFFSET '.(($scMemberPage-1)*25),[$scMemberClass])->fetch_all(MYSQLI_ASSOC);
  ?><section class="sc-member-section"><h3>Anggota <?= sc_e(class_label($scMembers)) ?></h3><p><?= $scMemberTotal ?> identitas siswa dan pemilik rekening. Data sumber dan histori tetap tersimpan.</p>
  <?php if(lop_ready($koneksi)): $sources=special_class_query($koneksi,'SELECT code,aliases FROM legacy_op_groups WHERE master_kelas_id=? ORDER BY code',[$scMemberClass])->fetch_all(MYSQLI_ASSOC);if($sources): ?><details class="sc-source"><summary>Asal kelompok Legacy</summary><p><?= sc_e(implode(', ',array_column($sources,'code'))) ?></p></details><?php endif;endif; ?>
  <?php if(!$members): ?><p class="sc-empty">Belum ada anggota di kelas ini.</p><?php else: ?><div class="sc-table-wrap"><table class="sc-table"><thead><tr><th>Nama / Identitas</th><th>Jenis</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($members as $member): ?><tr><td data-label="Nama"><strong><?= sc_e($member['name']) ?></strong><small><?= sc_e($member['identity']) ?></small></td><td data-label="Jenis"><?= $member['owner_type']==='student'?'Siswa':'Pemilik rekening non-siswa' ?></td><td data-label="Status"><?= $member['is_active']?'Aktif':'Diarsipkan' ?></td><td data-label="Tindakan"><a class="btn-tbl btn-tbl-edit" href="<?= sc_e($member['owner_type']==='student'?'siswa/daftar.php?edit='.(int)$member['id']:'legacy_accounts.php?'.http_build_query(['batch'=>$member['batch_id'],'class_id'=>$scMemberClass,'owner'=>$member['owner_id']]+$scContext)) ?>">Lihat Anggota</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
  <nav class="sc-pagination" aria-label="Halaman anggota"><span>Halaman <?= $scMemberPage ?> dari <?= max(1,(int)ceil($scMemberTotal/25)) ?></span><div class="sc-actions"><?php foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $delta=>$label): $next=$scMemberPage+$delta;if($next<1||($next-1)*25>=$scMemberTotal)continue; ?><a class="btn btn-ghost" href="<?= sc_e($scUrl(['special_members'=>$scMemberClass,'special_member_page'=>$next])) ?>"><?= $label ?></a><?php endforeach; ?></div></nav><a class="btn btn-ghost" href="<?= sc_e($scUrl()) ?>">Tutup Daftar Anggota</a></section><?php endif; ?>
  <?php if($scDelete&&!unit_all_readonly()): $usage=special_class_usage($koneksi,(int)$scDelete['id']);if(!$usage){$_SESSION['special_delete']=['id'=>(int)$scDelete['id'],'version'=>special_class_version($scDelete),'expires'=>time()+300,'key'=>bin2hex(random_bytes(32))];} ?>
  <section class="sc-confirm" id="special-delete-confirm" aria-labelledby="special-delete-title"><h3 id="special-delete-title"><?= $usage?'Kelas sudah pernah digunakan':'Hapus kelas khusus ini?' ?></h3><p><strong><?= sc_e($scDelete['nama_custom']) ?></strong></p><?php if($usage): ?><p>Anggota, histori, atau relasi Legacy masih menggunakan kelas ini. Gunakan Nonaktifkan untuk menghentikan pemilihan baru tanpa menghapus data.</p><div class="sc-actions"><a class="btn btn-ghost" data-sc-back href="<?= sc_e($scUrl()) ?>">Kembali</a><a class="btn btn-primary" href="<?= sc_e($scUrl(['special_edit'=>$scDelete['id']])) ?>">Ubah Status Kelas</a></div><?php else: ?><p>Kelas ini belum digunakan. Penghapusan hanya menghapus master kelas yang ditampilkan.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= sc_e($_SESSION['csrf_master_kelas']) ?>"><input type="hidden" name="aksi" value="hapus_custom"><input type="hidden" name="id" value="<?= (int)$scDelete['id'] ?>"><input type="hidden" name="delete_token" value="<?= sc_e($_SESSION['special_delete']['key']) ?>"><div class="sc-actions"><a class="btn btn-ghost" data-sc-back href="<?= sc_e($scUrl()) ?>">Batal</a><button class="btn btn-danger">Hapus Kelas Khusus</button></div></form><?php endif; ?></section><?php endif; ?>
  <?php endif; ?>
</section>
